def verify(result):
    delta = result['vars']['delta']
    return delta < 0 and 'elíptica' in result['correct']

def verify(result):
    A = result['vars']['A']
    B = result['vars']['B']
    C = result['vars']['C']
    return int(result['correct']) == (B**2 - 4*A*C)

def verify(result):
    v = result['vars']
    return v['delta'] > 0 and len([o for o in result['options'] if o['is_correct']]) >= 2
